          "replace": "        out = self._interest_states(seq)\n        weighted_out = out * self.compatibility_gain\n        pos_scores = (weighted_out * self.item_emb(pos)).sum(dim=-1)\n        neg_scores = (weighted_out * self.item_emb(neg)).sum(dim=-1)"
        },
